package com.leetcode.backend.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="contest_registrations",uniqueConstraints=@UniqueConstraint(columnNames={"contest_id","user_id"}),indexes=@Index(name="idx_registration_contest",columnList="contest_id")) public class ContestRegistration { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="contest_id",nullable=false) private Contest contest; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="registered_at",nullable=false) private LocalDateTime registeredAt; @PrePersist void created(){registeredAt=LocalDateTime.now();} public Long getId(){return id;} public Contest getContest(){return contest;} public void setContest(Contest v){contest=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public LocalDateTime getRegisteredAt(){return registeredAt;} }
